   276  int MqttSocket_Read(MqttClient *client, byte* buf, int buf_len, int timeout_ms)
   277  {
   278      int rc;
   279
   280      /* Validate arguments */
   281      if (client == NULL || client->net == NULL || client->net->read == NULL ||
   282          buf == NULL || buf_len <= 0) {
   283          return MQTT_CODE_ERROR_BAD_ARG;
   284      }
   285
   286      /* check for buffer position overflow */
   287      if (client->read.pos >= buf_len) {
   288          return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_OUT_OF_BUFFER);
   289      }
   290
   291  #ifdef WOLFMQTT_NONBLOCK
   292      rc = MqttSocket_ReadDo(client, &buf[client->read.pos],
   293          buf_len - client->read.pos, timeout_ms);
   294      if (rc >= 0) {
   295          client->read.pos += rc;
   296          client->read.total += rc;
   297          if (client->read.pos < buf_len) {
   298              rc = MQTT_CODE_CONTINUE;
   299          }
   300      }
   301      else if (rc == EWOULDBLOCK || rc == EAGAIN) {
   302          rc = MQTT_CODE_CONTINUE;
   303      }
   304
   305  #else
   306      do {
   307          rc = MqttSocket_ReadDo(client, &buf[client->read.pos],
   308              buf_len - client->read.pos, timeout_ms);
   309          if (rc <= 0) {
   310              break;
   311          }
   312          client->read.pos += rc;
   313          client->read.total += rc;
   314      } while (client->read.pos < buf_len);
   315  #endif /* WOLFMQTT_NONBLOCK */
   316
   317      /* handle return code */
   318      if (rc > 0) {
   319          /* return length read and reset position */
   320          rc = client->read.pos;
   321          client->read.pos = 0;
   322      }
   323
   324      return rc;
   325  }
